#pragma once
// 1-bit bitmap fonts (generated by tools/gen_assets.py) and UTF-8 text layout.
#include <cstdint>
#include <string>
#include <vector>

namespace ui {

struct Glyph {
  uint8_t w, h, adv;
  int8_t left, top;  // offset of the bitmap from the pen; top = rows above the baseline
  uint32_t offset;   // into Font::bits; rows packed MSB first without row padding
};
struct GlyphRange {
  uint32_t first, last, index;
};
struct Font {
  const uint8_t* bits;
  const Glyph* glyphs;
  const GlyphRange* ranges;
  uint16_t rangeCount;
  uint8_t ascent, descent, lineHeight;
  const char* name;
};

uint32_t utf8Next(const char*& s);  // 0 at end; invalid bytes -> U+FFFD
const Glyph* findGlyph(const Font& f, uint32_t cp);  // falls back to '?' for unknown code points
int textWidth(const Font& f, const char* s);
inline int textWidth(const Font& f, const std::string& s) { return textWidth(f, s.c_str()); }
// Shortens to fit maxWidth, appending an ellipsis; never splits a UTF-8 sequence.
std::string fitText(const Font& f, const std::string& s, int maxWidth);
// Greedy word wrap; the last allowed line is ellipsized. Returns the line count.
int wrapText(const Font& f, const std::string& s, int maxWidth, int maxLines, std::vector<std::string>& out);

}  // namespace ui
